  const getInputClass = (campo) => {
    if (!touched[campo]) return 'form-control';
    if (erroresValidacion[campo]) return 'form-control is-invalid';
    if (formData[campo]) return 'form-control is-valid';
    return 'form-control';
  };

  return (
    <div className="container" style={{ maxWidth: '500px' }}>
      <div className="card my-5">
        <div className="card-body">
          <h2 className="card-title text-center mb-4">
            {modo === 'login' ? 'Iniciar Sesión' : 'Crear Cuenta'}
          </h2>

          {modo === 'login' && (
            <>
              <div className="alert alert-info small mb-3">
                <strong>Admin:</strong> admin@admin.cl / admin.123
              </div>

              <div className="mb-3">
                <label className="form-label">Tipo de Usuario</label>
                <div className="d-flex gap-2">
                  <button
                    type="button"
                    className={`btn btn-sm ${tipoUsuario === 'usuario' ? 'btn-primary' : 'btn-outline-primary'}`}
                    onClick={() => setTipoUsuario('usuario')}
                    disabled={loading}
                  >
                    Usuario
                  </button>
                  <button
                    type="button"
                    className={`btn btn-sm ${tipoUsuario === 'admin' ? 'btn-warning' : 'btn-outline-warning'}`}
                    onClick={() => setTipoUsuario('admin')}
                    disabled={loading}
                  >
                    Administrador
                  </button>
                </div>
              </div>
            </>
          )}

          {error && (
            <div className="alert alert-danger alert-dismissible fade show">
              <strong>{error}</strong>
              <button type="button" className="btn-close" onClick={() => setError('')}></button>
            </div>
          )}

          <form onSubmit={handleSubmit} noValidate>
            <div className="mb-3">
              <label htmlFor="email" className="form-label">
                Email <span className="text-danger">*</span>
              </label>
              <input 
                type="text"
                className={getInputClass('email')}
                id="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                onBlur={() => handleBlur('email')}
                disabled={loading}
                placeholder="tu@email.com"
                autoComplete="email"
              />
              {touched.email && erroresValidacion.email && (
                <div className="invalid-feedback d-block">
                  {erroresValidacion.email}
                </div>
              )}
              {touched.email && !erroresValidacion.email && formData.email && (
                <div className="valid-feedback d-block">
                  ✓ Email válido
                </div>
              )}
              <small className="form-text text-muted">
                Ejemplo: usuario@dominio.com
              </small>
            </div>

            <div className="mb-3">
              <label htmlFor="password" className="form-label">
                Contraseña <span className="text-danger">*</span>
              </label>
              <input 
                type="password"
                className={getInputClass('password')}
                id="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                onBlur={() => handleBlur('password')}
                disabled={loading}
                placeholder="Mínimo 6 caracteres"
                autoComplete={modo === 'login' ? 'current-password' : 'new-password'}
              />
              {touched.password && erroresValidacion.password && (
                <div className="invalid-feedback d-block">
                  {erroresValidacion.password}
                </div>
              )}
              {touched.password && !erroresValidacion.password && formData.password && (
                <div className="valid-feedback d-block">
                  ✓ Contraseña válida
                </div>
              )}
              <small className="form-text text-muted">
                Mínimo 6 caracteres, máximo 50
              </small>
            </div>

            <div className="d-grid">
              <button 
                type="submit" 
                className="btn btn-primary" 
                disabled={loading || (touched.email && erroresValidacion.email) || (touched.password && erroresValidacion.password)}
              >
                {loading ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2"></span>
                    {modo === 'login' ? 'Ingresando...' : 'Registrando...'}
                  </>
                ) : (
                  modo === 'login' ? 'Ingresar' : 'Registrarse'
                )}
              </button>
            </div>
          </form>

          <div className="text-center mt-3">
            <p>
              {modo === 'login' ? '¿No tienes cuenta?' : '¿Ya tienes cuenta?'}{' '}
              <button className="btn btn-link p-0" onClick={cambiarModo} disabled={loading}>
                {modo === 'login' ? 'Regístrate aquí' : 'Inicia sesión'}
              </button>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
</content>
